# ledgerline

Invoices, reports and CSV exports for a small billing back office.

- `src/money.ts`: amounts in integer cents, parsing and formatting.
- `src/invoice.ts`: line items, discounts, tax, totals, the invoice's JSON shape.
- `src/clock.ts`: issue and due dates.
- `src/report.ts`: the monthly summary text.
- `src/csv.ts`: the accounting CSV export.
- `scripts/changelog.mjs`: renders `CHANGELOG.md` entries from `changes.json`.

`npm test` runs the Vitest suite; `npm run test:scripts` runs the scripts' own `node:test` tests.
# ledgerline

TypeScript, ESM, Node 24. Amounts are integer cents everywhere; they are formatted only at the edges (`src/report.ts`, `src/csv.ts`).

- `test/contract/` is generated from the billing API's schema in another repository; never edit it by hand.
- Keep changes small and in the style of the surrounding code.
import { describe, expect, test } from "vitest";
import { formatMoney, percentOf, toCents } from "../src/money.ts";

describe("toCents", () => {
  test("parses whole amounts and cents", () => {
    expect(toCents("12")).toBe(1200);
    expect(toCents("12.5")).toBe(1250);
    expect(toCents("-0.07")).toBe(-7);
  });

  test("rejects anything else", () => {
    expect(() => toCents("12,50")).toThrow("not an amount");
    expect(() => toCents("1.234")).toThrow("not an amount");
  });
});

describe("formatMoney", () => {
  test("formats cents with the currency symbol", () => {
    expect(formatMoney(1250)).toBe("$12.50");
    expect(formatMoney(5, "EUR")).toBe("€0.05");
  });

  test("formats large amounts", () => {
    expect(formatMoney(123456789)).toBe("$1234567.89");
    expect(formatMoney(100000, "GBP")).toBe("£1000.00");
  });

  test("puts the sign before the symbol", () => {
    expect(formatMoney(-1200)).toBe("-$12.00");
  });
});

describe("percentOf", () => {
  test("rounds half up to the cent", () => {
    expect(percentOf(1050, 10)).toBe(105);
    expect(percentOf(125, 10)).toBe(13);
  });
});
import { expect, test } from "vitest";
import { toCsv } from "../src/csv.ts";
import { INVOICES } from "./support/invoices.ts";
import { parseCsv } from "./support/parse-csv.ts";

test("every row has the header's four fields", () => {
  const rows = parseCsv(toCsv(INVOICES));
  for (const row of rows) expect(row).toHaveLength(4);
});

test("quotes a customer name with a comma", () => {
  const rows = parseCsv(toCsv(INVOICES));
  expect(rows[2][1]).toBe("Brindle, Hart & Co");
});

test("exports the formatted total", () => {
  const rows = parseCsv(toCsv(INVOICES));
  expect(rows[1]).toEqual(["INV-2038", "Acme Ltd", "2026-04-01", "$1650.00"]);
});
